sed -i 's/spriteData = spriteData.copy(uri = uri.toString())/try {\n                val inputStream = context.contentResolver.openInputStream(uri)\n                val file = java.io.File(context.filesDir, "sprite_${System.currentTimeMillis()}.png")\n                val outputStream = java.io.FileOutputStream(file)\n                inputStream?.copyTo(outputStream)\n                inputStream?.close()\n                outputStream.close()\n                spriteData = spriteData.copy(uri = android.net.Uri.fromFile(file).toString())\n            } catch (e: Exception) {\n                e.printStackTrace()\n                spriteData = spriteData.copy(uri = uri.toString())\n            }/' app/src/main/java/com/cfks/goosedroid/ui/screens/EditorScreen.kt
